      async function onSubmit(e) {
        console.log(pasword1Ref.current.value);
        console.log(pasword2Ref.current.value);
        e.preventDefault()
        const postData = {
          userName: userRef.current.value,
          password: pasword1Ref.current.value
        }
        console.log(postData);
        try {
          const res = await fetch('/register', {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json'
            },    
            body: JSON.stringify(postData)
          })
          const result = await res.json();
          console.log('Success:', result);
        } catch (error) {
          console.log('error');
          console.error('Error:', error);
        }
      }
    

    const validate = () => {
        let abc = pasword1Ref.current.value === pasword2Ref.current.value ? true : false;
        console.log(pasword1Ref.current.value);
        console.log(pasword2Ref.current.value);
        console.log(abc);
        return abc
    };

    return (
    <div className='container'>
        <div className='wrapper'>
            <span className='logo'>Chatapp</span>
            <span className='title'>Registrierung</span>
            <form onSubmit={onSubmit}>
                <input type="text" id='user' placeholder="Benutzername" onChange={setUser(document.getElementById("user"))}/>
                <input type="password" id='password1' placeholder="Passwort" ref={pasword1Ref}/>
                <input type="password" id='password2' placeholder="Passwort erneut" ref={pasword2Ref}/>
                <input style={{display:"none"}} type="file" id="file"/>
                <label htmlFor='file'>
                    <img src={ImageImport} alt=''/>
                    <span>gibt ein Profilfoto an</span>
                </label>
                <button type='submit' disabled={!validate}>Registrieren</button>
            </form>
            <p>Du hast schon einen Account? <Link to="/login">Login</Link></p>
        </div>
    </div>
  )
}

export default Register
